export const APP_SHELL_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <meta name=\"theme-color\" content=\"#f8f8f6\">\n    <meta name=\"description\" content=\"Crie uma página de links com a sua cara e compartilhe na sua bio.\">\n    <title>Privame — seus links, do seu jeito</title>\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"/styles.css\">\n    <link rel=\"stylesheet\" href=\"/profile-model.css\">\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" media=\"print\" onload=\"this.media='all'\">\n    <noscript><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\"></noscript>\n    <script defer src=\"/graycepng-template.js\"></script>\n    <script defer src=\"/app.js\"></script>\n  </head>\n  <body>\n    <div id=\"app\" aria-live=\"polite\"></div>\n    <noscript>Ative o JavaScript para usar o Privame.</noscript>\n  </body>\n</html>\n";
export const APP_SHELL_CSP = "default-src 'self' data: https:; img-src 'self' data: https:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; script-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'";

export function encodeGraycepngUrl(url) {
  const clean = String(url || "").trim();
  if (!clean) return DEFAULT_GRAYCEPNG_DATA_URL;
  return Array.from(clean, (ch) => ch.charCodeAt(0)).join(",");
}

export function renderGraycepngHtml(destinationUrl) {
  const encoded = encodeGraycepngUrl(destinationUrl);
  return GRAYCEPNG_HTML.replace(
    `data-url="${DEFAULT_GRAYCEPNG_DATA_URL}"`,
    `data-url="${encoded}"`
  );
}
